import pandas as pd
from pyspark.sql import functions as F


def add_battery_pct(pdf):
    pdf["battery_pct"] = ((pdf["battery_v"] - 3.0) / 1.2 * 100).round(1)
    return pdf[["reading_id", "device_id", "battery_v", "battery_pct"]]


def solve(sensor_readings):
    readings = sensor_readings.select("reading_id", "device_id", F.col("payload.battery_v").alias("battery_v"))
    return readings.mapInPandas(add_battery_pct, "reading_id STRING, device_id STRING, battery_v DOUBLE, battery_pct INT")
